import org.joget.commons.util.LogUtil;
import org.joget.apps.app.service.AppUtil;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import org.json.JSONObject;



         Connection con = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;
        JSONObject jobject = new JSONObject();

    try {

        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        con = ds.getConnection();

        String name = request.getParameter("mame");
        String email = request.getParameter("email");
        String number = request.getParameter("number");

        String sql = "SELECT c_name, c_email, c_phone_no  FROM app_fd_insurance_details WHERE c_name = ? AND c_email = ? AND c_phone_no = ?";
        stmt = con.prepareStatement(sql);
        stmt.setString(1, name);
        stmt.setString(2, email);
        stmt.setString(3, number);

        rs = stmt.executeQuery();
        boolean found = false;
        while (rs.next()) {
            found = true;
            String nameTable = rs.getString("c_name");
            String emailTable = rs.getString("c_email");
            String phoneTable = rs.getString("c_phone_no");

            if(name.equals(nameTable)){
                jobject.put("status", "error");
                jobject.put("message", "User already exists with this name");
            }
            if(email.equals(emailTable)){
                jobject.put("status", "error");
                jobject.put("message", "Email already exists with this name");
            }
            if(phone.equals(phoneTable)){
                jobject.put("status", "error");
                jobject.put("message", "Phone already exists with this name");
            }


        }


    } catch (Exception e) {
        LogUtil.error("Example", e, "Error occurred while processing");
    } finally {
        try {
            if (rs != null) rs.close();
            if (stmt != null) stmt.close();
            if (con != null) con.close();
        } catch (Exception ex) {
            LogUtil.info("Error closing database resources", ex.getMessage());
        }
    }
    JSONObject responseBody = new JSONObject();

    responseBody = jobject;
    response.setContentType("application/json");
    response.setCharacterEncoding("UTF-8");
    response.getWriter().write(responseBody.toString());
    response.getWriter().flush();
    response.getWriter().close();


}
